import"./chunk-2NFLSA4Y.js";var a={longitudinalWaves:{theory:{concept:"[[A longitudinal wave is a wave in which the particles of the medium oscillate along the direction in which the wave travels.]] Each particle pushes its neighbour, which pushes the next one, so compressions (where the particles crowd together) and rarefactions (where they spread apart) travel through the medium. The particles only oscillate around their places: the wave carries energy, not matter. Longitudinal waves can travel in solids, liquids and gases; sound in air is a longitudinal wave. As for any wave, v = f \xB7 \u03BB."},section:{longitudinal:{title:"Back and forth along the wave",text:"Push one end of a long spring sharply and a squeeze runs along it. Look at the red particle: it only swings a little to the left and right around its resting place (the dashed line), while the wave pattern moves on to the right. In a transverse wave the particles move across the direction of the wave; in a longitudinal wave they move along it."},regions:{title:"Compressions and rarefactions",text:"Where neighbouring particles move towards each other, they crowd together: a compression, where the density and the pressure are higher. Half a wavelength further, they move apart: a rarefaction, where the density and the pressure are lower. The dashed curve under the tube shows how crowded the particles are; the solid curve shows how far each one has moved. The compression is largest where the displacement curve falls most steeply."},relation:{title:"Wavelength, frequency and speed",text:"[[The wavelength \u03BB is the distance from one compression to the next.]] During one period T = 1/f the pattern moves forward by exactly one wavelength, so the wave speed is v = f \xB7 \u03BB. At the same speed, a higher frequency means a shorter wavelength. The speed is set by the medium \u2014 how stiff and how heavy it is \u2014 not by the source."},sound:{title:"Sound is a longitudinal wave",text:"A loudspeaker cone moves back and forth and pushes the air: compressions and rarefactions spread out at about 343 m/s (at 20 \xB0C). In water sound travels about 1480 m/s, in steel about 5900 m/s, because these are much stiffer. Sound needs a medium: in the vacuum of space there is nothing to push, so there is no sound."},compare:{title:"Longitudinal and transverse",text:"[[A wave on a string is transverse; sound is longitudinal.]] Earthquakes send out both: the fast longitudinal P waves arrive first, the slower transverse S waves later. S waves cannot cross a liquid, and their shadow on the far side of the Earth showed seismologists that the Earth's outer core is liquid."},hearing:{title:"What we hear",text:"People hear frequencies from about 20 Hz to 20 000 Hz. In air, 20 Hz means a wavelength of 17 m, 1000 Hz about 34 cm and 20 000 Hz just 1.7 cm. Bats and dolphins use ultrasound above our range to find their way, and doctors use it to see inside the body. Elephants talk with infrasound below our range."},check:{title:"Check your understanding",text:"In a longitudinal wave, which way do the particles move? (Along the direction of the wave.) What is the distance between two neighbouring compressions? (One wavelength.) A wave travels at 3 m/s with f = 1.5 Hz. What is its wavelength? (2 m.) Can sound travel through empty space? (No \u2014 there is nothing to compress.) Test each answer in the simulation."}},formula:{speed:"Wave speed: frequency times wavelength",period:"Period: the time of one vibration",wave:"Displacement of the particle that rests at x",compression:"Compression: minus the slope of the displacement"},assumption:{ideal:"An ideal medium: the wave keeps its shape and size; nothing is lost and nothing is reflected. The picture shows a window into an already running wave.",small:"The vibrations are small and sine-shaped, so the compression is proportional to the slope of the displacement.",scale:"Speeds and sizes are like a long spring; real sound in air is about 100 times faster. The curves under the tube are stretched vertically so that they can be seen."},param:{frequency:"Frequency",amplitude:"Amplitude (how far each particle moves)",speed:"Wave speed",timeStep:"Time step"},hint:{frequency:"How many times per second each particle swings back and forth.",amplitude:"The largest distance of a particle from its resting place.",speed:"How fast the pattern travels. It depends on the medium."},preset:{slow:"0.5 Hz",one:"1 Hz",fast:"2 Hz"},measure:{wavelength:"Wavelength",period:"Period",maxCompression:"Strongest compression",displacement:"Displacement of the red particle",compression:"Compression at the red particle",particleVelocity:"Velocity of the red particle",maxParticleSpeed:"Fastest particle speed"},view:{compression:"compression",rarefaction:"rarefaction",direction:"wave travels at {speed}",legend:"solid: displacement \xB7 dashed: crowding",regionsOption:"Compressions and rarefactions",particlesOption:"Particles",distancesOption:"Wavelength",vectorsOption:"Directions",curveOption:"Displacement and compression curves"},graph:{displacement:"Displacement of the red particle against time",compression:"Compression at the red particle against time"},challenge:{twoMetres:{title:"Two metres between compressions",description:"Make the compressions exactly 2 m apart.",hint:"\u03BB = v / f: at 3 m/s you need 1.5 Hz."},slowBeat:{title:"A slow beat",description:"Make each particle need exactly 2 s for one vibration.",hint:"T = 1 / f."},squeeze:{title:"A strong squeeze",description:"Make the particles crowd together so much that the density in a compression is at least 40 % higher.",hint:"The compression is 2\u03C0A/\u03BB: a large amplitude and a short wavelength."},speed:{title:"The right medium",description:"Make a wave with a wavelength of 4 m and a period of 2 s.",hint:"v = \u03BB / T: which wave speed is that?"},fastParticles:{title:"Fast particles, slow wave",description:"Make the particles reach at least 1.5 m/s while the wave travels at 3 m/s or slower.",hint:"The particles' top speed is A \xB7 2\u03C0f; it does not depend on the wave speed."}}}},s={sim:a};export{s as default,a as sim};
